## 5. Buttons & micro-interactions

### 5a. Magnetic button (JS)
**When:** hero primary CTAs — cursor pulls the button toward itself. Desktop only.
**Performance:** single rAF-driven transform; disable on touch + reduced motion.

```js
// Framework-agnostic; also in assets/motion-utils.js
export function magnetic(el, strength = 0.35) {
  if (window.matchMedia("(hover: none), (prefers-reduced-motion: reduce)").matches) return () => {};
  let raf = 0, tx = 0, ty = 0, cx = 0, cy = 0;
  const onMove = (e) => {
    const r = el.getBoundingClientRect();
    tx = (e.clientX - (r.left + r.width / 2)) * strength;
    ty = (e.clientY - (r.top + r.height / 2)) * strength;
  };
  const onLeave = () => { tx = 0; ty = 0; };
  const loop = () => {
    cx += (tx - cx) * 0.15;               // lerp = butter
    cy += (ty - cy) * 0.15;
    el.style.transform = `translate(${cx.toFixed(2)}px, ${cy.toFixed(2)}px)`;
    raf = requestAnimationFrame(loop);
  };
  el.addEventListener("mousemove", onMove);
  el.addEventListener("mouseleave", onLeave);
  raf = requestAnimationFrame(loop);
  return () => { cancelAnimationFrame(raf); el.removeEventListener("mousemove", onMove); el.removeEventListener("mouseleave", onLeave); };
}
```

