## 6. Card interactions

### 6a. 3D tilt-on-hover with glare
**When:** feature/pricing/media cards. Desktop only; subtle (≤8°).
**Performance:** one transform + one gradient position per card.

```js
// Also in assets/motion-utils.js
export function tilt(card, maxDeg = 8) {
  if (window.matchMedia("(hover: none), (prefers-reduced-motion: reduce)").matches) return () => {};
  card.style.transformStyle = "preserve-3d";
  const glare = document.createElement("div");
  glare.style.cssText = "position:absolute;inset:0;border-radius:inherit;pointer-events:none;opacity:0;transition:opacity 300ms;background:radial-gradient(circle at var(--gx,50%) var(--gy,50%),rgba(255,255,255,.25),transparent 60%)";
  card.style.position ||= "relative";
  card.appendChild(glare);
  const onMove = (e) => {
    const r = card.getBoundingClientRect();
    const px = (e.clientX - r.left) / r.width, py = (e.clientY - r.top) / r.height;
    card.style.transform = `perspective(800px) rotateX(${((0.5 - py) * maxDeg).toFixed(2)}deg) rotateY(${((px - 0.5) * maxDeg).toFixed(2)}deg) translateY(-4px)`;
    glare.style.setProperty("--gx", `${px * 100}%`);
    glare.style.setProperty("--gy", `${py * 100}%`);
  };
  const onEnter = () => { glare.style.opacity = "1"; card.style.transition = "transform 80ms"; };
  const onLeave = () => { glare.style.opacity = "0"; card.style.transition = "transform 400ms cubic-bezier(0.16,1,0.3,1)"; card.style.transform = ""; };
  card.addEventListener("pointermove", onMove);
  card.addEventListener("pointerenter", onEnter);
  card.addEventListener("pointerleave", onLeave);
  return () => { card.removeEventListener("pointermove", onMove); card.removeEventListener("pointerenter", onEnter); card.removeEventListener("pointerleave", onLeave); glare.remove(); };
}
```

